/* MIKROTIK CORE DEMO - CSS V1.0 */

.mkdemo-root {
  --cyan:#2fcaff;
  --green:#18efa5;
  --purple:#b775ff;
  --amber:#ffc247;
  --red:#ff506d;
  --muted:#8aacc6;
  --border:rgba(18,156,230,.62);
  --panel:linear-gradient(160deg,#061b2e,#03101f);
  width:100%;
  height:100%;
  min-height:670px;
  overflow:auto;
  padding:10px;
  background:radial-gradient(circle at 50% 8%,#093453,#020914 58%);
  color:#e9f8ff;
  font:12px Inter,Roboto,Arial,sans-serif;
  box-sizing:border-box;
}

.mkdemo-root *,
.mkdemo-root *:before,
.mkdemo-root *:after {box-sizing:border-box}

.mkdemo-root button,
.mkdemo-root select {font:inherit}

.mkdemo-card {
  border:1px solid var(--border);
  border-radius:10px;
  background:var(--panel);
  box-shadow:inset 0 0 0 1px #30aaff0b,0 0 15px #006da31b;
  overflow:hidden;
}

.mkdemo-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  min-height:65px;
  margin-bottom:9px;
}

.mkdemo-brand {
  display:flex;
  align-items:center;
  gap:10px;
  min-width:0;
}

.mkdemo-logo {
  width:42px;
  height:42px;
  border:2px solid var(--cyan);
  border-radius:10px;
  display:grid;
  place-items:center;
  color:#b4edff;
  font-weight:900;
  font-size:27px;
  box-shadow:0 0 15px #00bfff66;
}

.mkdemo-brand h1 {
  margin:0;
  font-size:clamp(16px,1.55vw,27px);
  letter-spacing:.2px;
  white-space:nowrap;
}

.mkdemo-brand h1 span {color:var(--cyan)}
.mkdemo-brand p {
  margin:5px 0 0;
  color:#93b7ce;
  font-size:9px;
  letter-spacing:1px;
}
.mkdemo-os {
  color:#73d7ff;
  border:1px solid #2786b4;
  border-radius:15px;
  padding:5px 9px;
  white-space:nowrap;
}

.mkdemo-disclaimer {
  padding:10px 15px;
  color:#ffe6a8;
  background:#362303bb;
  border:1px solid #d99d29;
  border-radius:7px;
  font-weight:850;
  letter-spacing:.6px;
  white-space:nowrap;
}

.mkdemo-head-status {
  display:flex;
  gap:7px;
}
.mkdemo-headbox {
  display:flex;
  align-items:center;
  gap:10px;
  min-width:126px;
  padding:9px;
  border:1px solid #167eae;
  border-radius:8px;
  background:#03182a;
}
.mkdemo-headbox small {
  display:block;
  margin:3px 0;
  font-size:9px;
  color:#85b8d1;
}
.mkdemo-headbox strong {
  display:block;
  font-size:12px;
  white-space:nowrap;
}
.mkdemo-head-icon {font-size:23px;color:var(--cyan)}
.mkdemo-led {
  display:block;
  width:12px;
  height:12px;
  border-radius:50%;
  background:var(--green);
  box-shadow:0 0 10px var(--green);
  animation:mkdBlink 1.8s infinite;
}

.mkdemo-kpis {
  display:grid;
  grid-template-columns:repeat(6,minmax(0,1fr));
  gap:7px;
  margin-bottom:8px;
}
.mkdemo-kpi {
  min-width:0;
  min-height:94px;
  padding:12px;
  display:flex;
  gap:10px;
  border-top:2px solid #27bfff;
}
.mkdemo-kicon {
  flex:0 0 37px;
  height:37px;
  display:grid;
  place-items:center;
  border:1px solid #288ec0;
  border-radius:9px;
  background:#082c46;
  color:var(--cyan);
  font-size:23px;
}
.mkdemo-kicon.purple {color:var(--purple)}
.mkdemo-kicon.amber {color:var(--amber)}
.mkdemo-kicon.green {color:var(--green)}
.mkdemo-kbody {min-width:0;flex:1}
.mkdemo-kbody small {
  display:block;
  color:#75d7ff;
  font-size:10px;
  font-weight:800;
}
.mkdemo-kbody strong {
  display:block;
  margin:6px 0;
  font-size:clamp(17px,1.4vw,25px);
  white-space:nowrap;
}
.mkdemo-kbody > span {
  color:#8daec4;
  font-size:9px;
}
.mkdemo-spark {
  width:100%;
  height:24px;
  color:#2cc8ff;
}
.mkdemo-spark.purple {color:var(--purple)}
.mkdemo-spark.amber {color:var(--amber)}
.mkdemo-spark svg {display:block;width:100%;height:100%}
.mkdemo-interface-leds {
  display:flex;
  gap:3px;
  margin:8px 0;
}
.mkdemo-interface-leds i {
  display:block;
  height:8px;
  flex:1;
  background:#264258;
  border-radius:2px;
}
.mkdemo-interface-leds i.up {
  background:var(--green);
  box-shadow:0 0 5px #18efa566;
}
.mkdemo-interface-leds i.down {background:#b83651}

/* ROUTER STAGE */

.mkdemo-device {
  padding:9px;
  margin-bottom:8px;
}
.mkdemo-section-head {
  min-height:24px;
  margin-bottom:7px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:9px;
}
.mkdemo-section-head > strong {
  color:#61d5ff;
  font-size:11px;
  letter-spacing:.3px;
}
.mkdemo-section-head > span {
  color:#91b4c9;
  font-size:10px;
}
.mkdemo-status-chips {display:flex;gap:6px}
.mkdemo-chip {
  padding:5px 9px;
  font-size:10px;
  border-radius:13px;
  border:1px solid #36536a;
}
.mkdemo-chip.up {color:#72ffd0;background:#064332}
.mkdemo-chip.down {color:#ffc0c9;background:#54202f}
.mkdemo-chip.warning {color:#ffdb85;background:#4a3513}

.mkdemo-device-stage {
  height:260px;
  position:relative;
  isolation:isolate;
  background:
    radial-gradient(ellipse at 50% 28%,#14608c50,transparent 66%),
    linear-gradient(#061526,#030e1b);
  border-radius:9px;
  overflow:hidden;
}
.mkdemo-device-stage:after {
  content:"";
  position:absolute;
  z-index:0;
  inset:55% 0 0;
  pointer-events:none;
  background:
    repeating-linear-gradient(90deg,#1aaaff0e 0 1px,transparent 1px 55px),
    repeating-linear-gradient(0deg,#1aaaff0e 0 1px,transparent 1px 35px);
  transform:perspective(230px) rotateX(38deg);
}
.mkdemo-device-glow {
  position:absolute;
  inset:10% 10% auto;
  height:135px;
  border-radius:50%;
  filter:blur(36px);
  background:#138ee235;
  pointer-events:none;
}

.mkdemo-router {
  position:absolute;
  z-index:3;
  left:3%;
  right:3%;
  top:10px;
  height:116px;
  display:grid;
  grid-template-columns:28px minmax(0,1fr) 28px;
  filter:drop-shadow(0 12px 12px #000b);
}
.mkdemo-ear {
  position:relative;
  border:2px solid #8696a9;
  border-radius:8px;
  background:linear-gradient(90deg,#586d81,#b3c3d4,#3c5167);
}
.mkdemo-ear span {
  position:absolute;
  left:50%;
  transform:translateX(-50%);
  width:10px;
  height:11px;
  border:2px solid #a0b6c9;
  border-radius:4px;
  background:#081624;
}
.mkdemo-ear span:first-child {top:15px}
.mkdemo-ear span:last-child {bottom:15px}

.mkdemo-chassis {
  position:relative;
  overflow:hidden;
  border:2px solid #5e778f;
  border-radius:7px;
  background:
    linear-gradient(170deg,#4a607a 0%,#24344c 22%,#111f32 48%,#293c54 84%,#162435);
  box-shadow:inset 0 2px 3px #b4d0e377,inset 0 -8px 12px #0007;
}
.mkdemo-chassis-top {
  position:absolute;
  inset:0 0 auto;
  height:13px;
  background:repeating-linear-gradient(
    90deg,#6e819022 0 8px,#060e17aa 8px 12px
  );
}
.mkdemo-router-brand {
  position:absolute;
  top:30px;
  left:2%;
  width:16%;
  color:#d9e8fa;
}
.mkdemo-router-brand em {
  display:block;
  font-size:clamp(12px,1.5vw,26px);
  font-weight:900;
  letter-spacing:-.5px;
}
.mkdemo-router-brand small {
  display:block;
  font-size:8px;
  margin-top:6px;
  color:#a9c3d6;
}
.mkdemo-console {
  position:absolute;
  left:18%;
  top:37px;
  text-align:center;
  color:#a3bacb;
  font-size:7px;
}
.mkdemo-socket.small {
  width:22px;
  height:23px;
  background:#030911;
  border:3px solid #74879a;
  border-radius:3px;
  margin:0 auto 4px;
}
.mkdemo-router-ports {
  position:absolute;
  left:25%;
  right:19%;
  top:23px;
  display:flex;
  justify-content:space-evenly;
  gap:3px;
}
.mkdemo-router-port {
  flex:1;
  min-width:0;
  max-width:48px;
  position:relative;
  text-align:center;
  cursor:pointer;
  color:#d9ebf4;
}
.mkdemo-router-port small {
  display:block;
  font-size:8px;
  margin:0 0 5px;
}
.mkdemo-router-port .mkdemo-portled {
  display:block;
  margin:0 auto 5px;
  width:7px;
  height:7px;
  background:#ff506d;
  border-radius:50%;
  box-shadow:0 0 7px #ff506d;
}
.mkdemo-router-port.up .mkdemo-portled {
  background:var(--green);
  box-shadow:0 0 9px var(--green);
  animation:mkdBlink 1.5s infinite;
}
.mkdemo-router-port .mkdemo-socket {
  position:relative;
  display:block;
  height:29px;
  width:100%;
  border:2px solid #8395a4;
  border-radius:2px;
  background:linear-gradient(#07121d,#01070d);
  box-shadow:inset 0 3px 3px #000,inset 0 -2px 2px #425367;
}
.mkdemo-router-port .mkdemo-socket:after {
  content:"";
  position:absolute;
  left:15%;
  right:15%;
  top:11px;
  height:6px;
  background:repeating-linear-gradient(
    90deg,#d7b361 0 3px,#151f2b 3px 5px
  );
}
.mkdemo-router-port.up .mkdemo-socket {
  border-color:#4fddbb;
  box-shadow:0 0 8px #0cbb9c66,inset 0 4px 5px #000;
}
.mkdemo-router-port.down .mkdemo-socket {
  border-color:#bf4f61;
}
.mkdemo-router-port.sfp .mkdemo-socket {
  border-color:#48bffe;
}
.mkdemo-router-port:hover .mkdemo-socket {
  outline:2px solid #60d9ff;
}
.mkdemo-vent {
  position:absolute;
  right:2%;
  top:26px;
  width:14%;
  height:60px;
  opacity:.7;
  background:radial-gradient(circle,#02060b 45%,transparent 52%) 0 0 / 9px 9px;
}
.mkdemo-chassis-label {
  position:absolute;
  right:2%;
  bottom:9px;
  color:#b4c8dc;
  text-align:right;
  font-size:9px;
  letter-spacing:1px;
}
.mkdemo-chassis-label small {
  display:block;
  font-size:7px;
  margin-top:4px;
}
.mkdemo-cables {
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  overflow:hidden;
  z-index:2;
  pointer-events:none;
}
.mkdemo-cable {
  fill:none;
  stroke-width:2;
  stroke-linecap:round;
  filter:drop-shadow(0 0 4px currentColor);
}
.mkdemo-particle {
  filter:url(#mkd-glow-filter);
}
.mkdemo-destinations {
  position:absolute;
  z-index:4;
  bottom:10px;
  left:7%;
  right:7%;
  display:grid;
  grid-template-columns:repeat(6,minmax(0,1fr));
  gap:9px;
}
.mkdemo-destination {
  min-width:0;
  text-align:center;
  color:#ddf4ff;
}
.mkdemo-dest-icon {
  margin:0 auto 5px;
  width:33px;
  height:33px;
  border:1px solid #21baff;
  color:#43ccff;
  border-radius:50%;
  display:grid;
  place-items:center;
  font-size:22px;
  background:#06243ce6;
  box-shadow:0 0 11px #009fff44;
}
.mkdemo-destination strong {
  display:block;
  font-size:10px;
  white-space:nowrap;
}
.mkdemo-destination span {
  display:block;
  margin-top:4px;
  font-size:9px;
  color:#a5c5d7;
}

/* INTERFACE CARDS */

.mkdemo-ports-section {
  padding:9px;
  margin-bottom:8px;
}
.mkdemo-filters {display:flex;gap:4px}
.mkdemo-filters button {
  color:#acd6e9;
  background:#08263e;
  border:1px solid #246b94;
  border-radius:5px;
  padding:4px 9px;
  cursor:pointer;
}
.mkdemo-filters button.active {
  border-color:#35caff;
  background:#0a5481;
  color:white;
}
.mkdemo-port-grid {
  display:grid;
  grid-template-columns:repeat(14,minmax(0,1fr));
  gap:5px;
}
.mkdemo-port-card {
  min-width:0;
  min-height:80px;
  padding:7px 5px;
  border:1px solid #197caa;
  border-radius:7px;
  background:#061b2d;
  cursor:pointer;
  text-align:center;
}
.mkdemo-port-card.up {border-color:#0c9678}
.mkdemo-port-card.down {border-color:#a43b50}
.mkdemo-port-card.selected {
  outline:2px solid #45cfff;
  box-shadow:0 0 15px #25bfff55;
}
.mkdemo-port-card strong {
  display:block;
  margin:3px 0 5px;
  font-size:11px;
}
.mkdemo-port-card .mkdemo-dot {
  float:left;
  margin:4px 0 0;
}
.mkdemo-port-card small {
  display:block;
  font-size:8px;
  color:#95bcd1;
  margin:5px 0;
}
.mkdemo-port-card svg {
  width:100%;
  height:22px;
  display:block;
}
.mkdemo-port-card .mkdemo-pill {
  display:inline-block;
}
.mkdemo-pill {
  padding:3px 7px;
  font-size:9px;
  font-weight:bold;
  border-radius:10px;
}
.mkdemo-pill.up {background:#09563e;color:#85ffcc}
.mkdemo-pill.down {background:#662333;color:#ffc4ce}
.mkdemo-dot {
  display:inline-block;
  width:8px;height:8px;
  border-radius:50%;
}
.mkdemo-dot.green {background:var(--green)}
.mkdemo-dot.cyan {background:var(--cyan)}
.mkdemo-dot.down {background:var(--red)}

/* BOTTOM PANELS */

.mkdemo-bottom {
  display:grid;
  grid-template-columns:1.5fr 1.1fr .85fr .9fr;
  gap:8px;
}
.mkdemo-bottom > article {
  min-width:0;
  height:260px;
  padding:10px;
}
.mkdemo-bottom select {
  max-width:150px;
  padding:6px;
  color:#cceeff;
  background:#06243d;
  border:1px solid #276e9c;
  border-radius:6px;
}
.mkdemo-chart-area {
  height:177px;
  position:relative;
}
.mkdemo-chart-area > svg {
  width:100%;
  height:100%;
}
.mkdemo-chart-tooltip {
  display:none;
  position:absolute;
  top:5px;
  background:#061827f5;
  border:1px solid #31baff;
  color:white;
  padding:8px;
  border-radius:5px;
  pointer-events:none;
  z-index:5;
  font-size:10px;
}
.mkdemo-chart-times {
  display:flex;
  justify-content:space-between;
  color:#86b4d0;
  font-size:9px;
  margin:2px 4px;
}
.mkdemo-chart-legend {
  display:flex;
  gap:13px;
  align-items:center;
  flex-wrap:wrap;
  margin-top:7px;
  font-size:10px;
}
.mkdemo-chart-legend > div {
  display:flex;
  align-items:center;
  gap:5px;
}
.mkdemo-chart-legend strong {color:#dceffc}
.mkdemo-chart-legend > span {color:#8faec4}
.mkdemo-scroll {
  max-height:213px;
  overflow:auto;
  scrollbar-width:thin;
  scrollbar-color:#1b6588 transparent;
}
.mkdemo-table {
  width:100%;
  border-collapse:collapse;
  text-align:left;
  font-size:10px;
}
.mkdemo-table th {
  color:#83b7d1;
  font-size:9px;
}
.mkdemo-table td,
.mkdemo-table th {
  padding:7px 5px;
  border-bottom:1px solid #24506a77;
  white-space:nowrap;
}
.mkdemo-table tbody tr {cursor:pointer}
.mkdemo-table tbody tr:hover {background:#10446766}
.mkdemo-list-row {
  display:flex;
  justify-content:space-between;
  gap:8px;
  padding:9px 2px;
  border-bottom:1px solid #24506a77;
  font-size:10px;
}
.mkdemo-list-row strong {
  display:block;
  margin-bottom:5px;
}
.mkdemo-list-row small {
  color:#93b4c9;
}
.mkdemo-list-row .severity {
  font-size:9px;
  font-weight:bold;
  white-space:nowrap;
}
.mkdemo-list-row.critical {color:#ff8aa0}
.mkdemo-list-row.warning {color:#ffd273}
.mkdemo-count {
  padding:4px 8px;
  border-radius:7px;
  background:#103b5c;
  color:#9cdeff;
}
.mkdemo-count.alert {
  background:#632338;
  color:#ffb8c8;
}

.mkdemo-footer {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:10px;
  margin-top:8px;
  padding:9px 12px;
  border:1px solid #176b98;
  border-radius:8px;
  font-size:10px;
  color:#a4c8d9;
}
.mkdemo-footer span:first-child {
  color:#ffd175;
  font-weight:bold;
}
.mkdemo-footer span:nth-child(3) {color:#59ffbd}
.mkdemo-footer button {
  padding:5px 10px;
  color:#cceeff;
  background:#073353;
  border:1px solid #237ba9;
  border-radius:5px;
  cursor:pointer;
}

/* MODAL */

.mkdemo-overlay[hidden] {display:none!important}
.mkdemo-overlay {
  position:fixed;
  inset:0;
  z-index:99999;
  display:grid;
  place-items:center;
  background:#000b;
  backdrop-filter:blur(4px);
}
.mkdemo-modal {
  width:min(90vw,470px);
  position:relative;
  padding:23px;
  border:1px solid #26bfff;
  border-radius:13px;
  background:linear-gradient(#082640,#031321);
  box-shadow:0 0 40px #009cff55;
}
.mkdemo-modal h2 {
  color:#68d9ff;
  margin:0 0 16px;
}
.mkdemo-modal-row {
  display:flex;
  justify-content:space-between;
  gap:20px;
  padding:10px 0;
  border-bottom:1px solid #235572;
}
.mkdemo-modal-row span {color:#a6c5d7}
.mkdemo-modal-row b {text-align:right}
.mkdemo-close {
  position:absolute;
  top:10px;
  right:14px;
  font-size:25px!important;
  color:white;
  background:transparent;
  border:0;
  cursor:pointer;
}

@keyframes mkdBlink {
  0%,100% {opacity:1}
  50% {opacity:.35}
}

@media(max-width:1450px) {
  .mkdemo-header {flex-wrap:wrap}
  .mkdemo-disclaimer {order:3;margin:auto}
  .mkdemo-kpis {grid-template-columns:repeat(3,minmax(0,1fr))}
  .mkdemo-bottom {grid-template-columns:1fr 1fr}
  .mkdemo-port-grid {grid-template-columns:repeat(7,minmax(0,1fr))}
  .mkdemo-router-brand small {display:none}
}

@media(max-width:850px) {
  .mkdemo-head-status {flex-wrap:wrap}
  .mkdemo-device-stage {height:300px}
  .mkdemo-router {height:100px}
  .mkdemo-router-ports {left:23%;right:5%}
  .mkdemo-console,.mkdemo-vent {display:none}
  .mkdemo-router-brand {left:2%;width:19%}
  .mkdemo-chassis-label {display:none}
  .mkdemo-destinations {left:2%;right:2%;gap:2px}
  .mkdemo-destination strong {font-size:8px}
  .mkdemo-destination span {font-size:8px}
  .mkdemo-bottom {grid-template-columns:1fr}
  .mkdemo-kpis {grid-template-columns:repeat(2,minmax(0,1fr))}
}

@media(max-width:580px) {
  .mkdemo-brand h1 {font-size:17px}
  .mkdemo-os {display:none}
  .mkdemo-port-grid {grid-template-columns:repeat(3,minmax(0,1fr))}
  .mkdemo-destinations {grid-template-columns:repeat(3,1fr)}
  .mkdemo-device-stage {height:375px}
  .mkdemo-router-ports {gap:1px;top:22px}
  .mkdemo-router-port small {font-size:6px}
  .mkdemo-router-port .mkdemo-socket {height:22px}
  .mkdemo-dest-icon {width:25px;height:25px;font-size:17px}
  .mkdemo-section-head {flex-wrap:wrap}
  .mkdemo-header {justify-content:center}
  .mkdemo-disclaimer {font-size:9px}
}
@media(prefers-reduced-motion:reduce) {
  .mkdemo-led,.mkdemo-router-port .mkdemo-portled {
    animation:none!important;
  }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
(function () {
  'use strict';

  /* ======================================================
     MIKROTIK CORE DEMO V1.0
     GRAFANA HTML GRAPHICS

     SOMENTE DADOS FICTICIOS
