  function rate(n) {
    if (n === null || !Number.isFinite(n)) return 'SEM DADO';
    const a = Math.abs(n);
    if (a >= 1e9) return (n / 1e9).toFixed(2) + ' Gbps';
    if (a >= 1e6) return (n / 1e6).toFixed(2) + ' Mbps';
    if (a >= 1e3) return (n / 1e3).toFixed(2) + ' Kbps';
    return n.toFixed(0) + ' bps';
  }

  function esc(v) {
    return String(v == null ? '' : v).replace(/[&<>"']/g, c => ({
      '&':'&amp;', '<':'&lt;', '>':'&gt;',
      '"':'&quot;', "'":'&#39;'
    })[c]);
  }

  function svgEl(tag, attrs) {
    const el = document.createElementNS(NS, tag);
    Object.entries(attrs || {}).forEach(([key, value]) => {
      el.setAttribute(key, String(value));
    });
    return el;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function portOf(name) {
    return PORTS.find(p => p.name === name);
  }

  function hash(s) {
    let x = 2166136261;
    for (let i = 0; i < s.length; i++) {
      x ^= s.charCodeAt(i);
      x = Math.imul(x, 16777619);
    }
    return x >>> 0;
  }

  // Gerador deterministico. Mantem os graficos plausiveis.
  function rand(seed) {
    let x = seed >>> 0;
    return function () {
      x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
      return x / 4294967296;
    };
  }

  function makeHistory(name, base, direction) {
    const r = rand(hash(name + direction));
    const arr = [];

    for (let i = 0; i < 180; i++) {
      const wave =
        0.78 +
        0.13 * Math.sin(i * 0.13 + r() * 0.4) +
        0.07 * Math.sin(i * 0.49) +
        0.08 * (r() - 0.5);

      let burst = 0;

      [31, 74, 108, 145, 171].forEach((center, j) => {
        const width = 2.5 + j % 3;
        burst += (0.34 + j * 0.08) *
          Math.exp(-Math.pow((i-center)/width, 2));
      });

      arr.push(Math.max(0, base * (wave + burst)));
    }

    return arr;
  }

  const HIST = {};
  PORTS.forEach(p => {
    HIST[p.name] = {
      rx:makeHistory(p.name, p.rx, 'rx'),
      tx:makeHistory(p.name, p.tx, 'tx')
    };
  });

  /* ======================================================
     ESTADO DA INTERFACE E ATUALIZACAO SIMULADA
     ====================================================== */

  const oldState = root._mkdState || {};

  const state = {
    selected: portOf(oldState.selected)
      ? oldState.selected : 'sfp-srv2',
