  root._mkdState = state;

  function current(p, direction) {
    if (p.status === 'down') return 0;

    const base = direction === 'rx' ? p.rx : p.tx;
    const t = state.tick;

    return Math.max(0, base * (
      0.94 +
      0.07 * Math.sin(t * 0.35 + hash(p.name) % 9) +
      0.035 * Math.cos(t * 0.78)
    ));
  }

  function spark(values, color) {
    if (!values.length) return '';

    const max = Math.max(1, ...values);
    const min = Math.min(0, ...values);

    const coordinates = values.map((v, i) => {
      const x = i / Math.max(1, values.length - 1) * 160;
      const y = 25 - (v - min) / (max - min || 1) * 21;
      return [x, y];
    });

    const path = coordinates.map((p, i) =>
      (i ? 'L ' : 'M ') + p[0].toFixed(1) +
      ' ' + p[1].toFixed(1)
    ).join(' ');

    return '<svg viewBox="0 0 160 28" preserveAspectRatio="none">' +
      '<path d="' + path + '" fill="none" stroke="' +
      color + '" stroke-width="1.6"/>' +
      '</svg>';
  }

