  /* ======================================================
     GRAFICO PRINCIPAL RX / TX
     ====================================================== */

  function chartPath(arr, maxValue, fill) {
    const coordinates = arr.map((v,i) => ({
      x: i / Math.max(1,arr.length-1) * 700,
      y: 248 - (v / maxValue) * 224
    }));

    const d = coordinates.map((p,i) =>
      (i ? 'L ' : 'M ') +
      p.x.toFixed(2) + ' ' + p.y.toFixed(2)
    ).join(' ');

    return fill ? d + ' L 700 248 L 0 248 Z' : d;
  }

  function drawChart() {
    const name = state.selected;
    const hist = HIST[name];
    if (!hist) return;

    const rx = hist.rx;
    const tx = hist.tx;
    const top = Math.max(1, ...rx, ...tx) * 1.12;

    const grid = $('mkd-chart-grid');
    if (grid) {
      grid.replaceChildren();

      for (let i = 0; i <= 4; i++) {
        const y = 24 + i*56;
        grid.appendChild(svgEl('line', {
          x1:0, y1:y, x2:700, y2:y,
          stroke:'#24618a',
          'stroke-dasharray':'5 5',
          opacity:0.55
        }));

        const x = i*175;
        grid.appendChild(svgEl('line', {
          x1:x, y1:0, x2:x, y2:248,
          stroke:'#24618a',
          'stroke-dasharray':'4 6',
          opacity:0.35
        }));
      }
    }

    $('mkd-chart-rx-path').setAttribute(
      'd', chartPath(rx, top, false)
    );
    $('mkd-chart-tx-path').setAttribute(
      'd', chartPath(tx, top, false)
    );
    $('mkd-chart-rx-area').setAttribute(
      'd', chartPath(rx, top, true)
    );
    $('mkd-chart-tx-area').setAttribute(
      'd', chartPath(tx, top, true)
    );

    const end = Date.now();
    const times = $('mkd-chart-times');
    if (times) {
      times.innerHTML = Array.from({length:7},(_,i) => {
        const d = new Date(end - (6-i)*3600000);
        return '<span>' +
          d.toLocaleTimeString('pt-BR',{
            hour:'2-digit',minute:'2-digit'
          }) + '</span>';
      }).join('');
    }

    const p = portOf(name);

    text('mkd-chart-rx-value', rate(current(p,'rx')));
    text('mkd-chart-tx-value', rate(current(p,'tx')));
    text('mkd-chart-peak',
      'Máx RX: ' + rate(Math.max(...rx)) +
      ' | Máx TX: ' + rate(Math.max(...tx)));

    root._mkdChartScale = top;
  }

  function setupChartHover() {
    const svg = $('mkd-chart');
    const tooltip = $('mkd-chart-tooltip');

    if (!svg || !tooltip) return;

    svg.onmousemove = function (e) {
      const rect = svg.getBoundingClientRect();
      const ratio = clamp(
        (e.clientX - rect.left) / rect.width,
        0, 1
      );

      const index = Math.round(ratio * 179);
      const hist = HIST[state.selected];
      if (!hist) return;

      const x = index / 179 * 700;
      const top = root._mkdChartScale || 1;

      const yrx = 248 - hist.rx[index]/top*224;
      const ytx = 248 - hist.tx[index]/top*224;

      const cross = $('mkd-crosshair');
      cross.setAttribute('x1',x);
      cross.setAttribute('x2',x);
      cross.setAttribute('y1',0);
      cross.setAttribute('y2',248);
      cross.setAttribute('opacity',1);

      $('mkd-chart-rx-dot').setAttribute('cx',x);
      $('mkd-chart-rx-dot').setAttribute('cy',yrx);
      $('mkd-chart-tx-dot').setAttribute('cx',x);
      $('mkd-chart-tx-dot').setAttribute('cy',ytx);

      tooltip.style.display = 'block';
      tooltip.style.left = clamp(
        e.clientX - rect.left, 0,
        Math.max(0,rect.width-180)
      ) + 'px';

      tooltip.textContent =
        'RX: ' + rate(hist.rx[index]) +
        ' | TX: ' + rate(hist.tx[index]);
    };

    svg.onmouseleave = function () {
      tooltip.style.display = 'none';
      $('mkd-crosshair').setAttribute('opacity',0);
    };
  }

  /* ======================================================
     CABOS ANIMADOS ENTRE O ROTEADOR E OS DESTINOS
     ====================================================== */

  let animated = [];

  function rebuildCables() {
    const stage = $('mkd-stage');
    const svg = $('mkd-cable-svg');
    const paths = $('mkd-cable-paths');
    const particles = $('mkd-cable-packets');

    if (!stage || !svg || !paths || !particles) return;

    const box = stage.getBoundingClientRect();
    if (box.width < 50 || box.height < 50) return;

    svg.setAttribute('viewBox',
      '0 0 ' + box.width + ' ' + box.height);

    paths.replaceChildren();
    particles.replaceChildren();
    animated = [];

    GROUPS.forEach((group,i) => {
      const src = $$('.mkdemo-router-port').find(el =>
        el.dataset.port === group.source
      );
      const dest = qDest(group.id);
      if (!src || !dest) return;

      const a = src.getBoundingClientRect();
      const b = dest.getBoundingClientRect();

      const x1 = a.left + a.width/2 - box.left;
      const y1 = a.bottom - box.top;

      const x2 = b.left + b.width/2 - box.left;
      const y2 = b.top - box.top + 4;

      const bend = Math.max(17,(y2-y1)*0.53);

      const d = 'M ' + x1 + ' ' + y1 +
        ' C ' + x1 + ' ' + (y1+bend) +
        ' ' + x2 + ' ' + (y2-bend*0.3) +
        ' ' + x2 + ' ' + y2;

      const glow = svgEl('path',{
        d:d,
        stroke:group.color,
        'stroke-width':6,
        opacity:.15,
        fill:'none',
        filter:'url(#mkd-glow-filter)'
      });

      const path = svgEl('path',{
        d:d,
        class:'mkdemo-cable',
        stroke:group.color
      });

      paths.appendChild(glow);
      paths.appendChild(path);

      const length = path.getTotalLength();

      // RX e TX caminham em direcoes opostas.
      const density = clamp(
        Math.round(group.rx/30000000)+2,2,6
      );

      for (let direction = 0; direction < 2; direction++) {
        for (let j = 0; j < density; j++) {
          const dot = svgEl('circle',{
            r:direction === 0 ? 2.7 : 2.2,
            fill:direction === 0 ? group.color : '#d6bcff',
            class:'mkdemo-particle'
          });

          particles.appendChild(dot);

          animated.push({
            path:path,
            length:length,
            dot:dot,
            direction:direction,
            speed:0.12 + group.rx/1500000000,
            offset:j/density + i*.091
          });
        }
      }

      const label = $('mkd-dest-' + group.id);
      if (label) {
        label.textContent = '↓ ' + rate(group.rx) +
          ' / ↑ ' + rate(group.tx);
      }

      const icon = dest.querySelector('.mkdemo-dest-icon');
      if (icon) {
        icon.style.borderColor = group.color;
        icon.style.color = group.color;
      }
    });
  }

  function qDest(id) {
    return root.querySelector(
      '.mkdemo-destination[data-dest="' + id + '"]'
    );
  }

  function animationFrame(timestamp) {
    if (!root.isConnected) {
      root._mkdFrame = null;
      return;
    }

    const seconds = timestamp/1000;

    animated.forEach(p => {
      let progress =
        (seconds*p.speed+p.offset)%1;

      if (p.direction === 1) {
        progress = 1-progress;
      }

      const point = p.path.getPointAtLength(
        p.length*progress
      );

      p.dot.setAttribute('cx',point.x);
      p.dot.setAttribute('cy',point.y);

      p.dot.setAttribute('opacity',
        .6 + .4*Math.sin(progress*Math.PI));
    });

    root._mkdFrame = requestAnimationFrame(
      animationFrame
    );
  }

