  function showModal(title, rows) {
    const overlay = $('mkd-overlay');
    const content = $('mkd-modal-content');

    if (!overlay || !content) return;

    content.innerHTML =
      '<h2>' + esc(title) + '</h2>' +
      rows.map(item =>
        '<div class="mkdemo-modal-row">' +
        '<span>' + esc(item[0]) + '</span>' +
        '<b>' + esc(item[1]) + '</b>' +
        '</div>'
      ).join('') +
      '<div style="margin-top:16px;color:#ffd273">' +
      'DEMONSTRACAO - DADOS FICTICIOS' +
      '</div>';

    overlay.hidden = false;
  }

  function openPort(name) {
    const p = portOf(name);
    if (!p) return;

    selectPort(name);

    const rxHistory = HIST[p.name].rx;
    const txHistory = HIST[p.name].tx;

    showModal('INTERFACE ' + p.name.toUpperCase(),[
      ['Status', p.status.toUpperCase() + ' (DEMO)'],
      ['Descricao', p.desc],
      ['RX', rate(current(p,'rx'))],
      ['TX', rate(current(p,'tx'))],
      ['Pico RX', rate(Math.max(...rxHistory))],
      ['Pico TX', rate(Math.max(...txHistory))],
      ['Grupo', p.group || 'Nao atribuido'],
      ['Origem', 'Simulacao local']
    ]);
  }

  /* ======================================================
     EVENTOS
     ====================================================== */

  root.onclick = function (event) {
    const t = event.target;

    if (t.closest('#mkd-modal-close') ||
        t === $('mkd-overlay')) {
      $('mkd-overlay').hidden = true;
      return;
    }

    const port = t.closest('[data-port]');
    if (port) {
      openPort(port.dataset.port);
      return;
    }

    const filter = t.closest('[data-filter]');
    if (filter) {
      state.filter = filter.dataset.filter;
      buildPortCards();
      return;
    }

    if (t.closest('#mkd-diagnostic-button')) {
      const up = PORTS.filter(p=>p.status==='up').length;
      const down = PORTS.length-up;

      showModal('DIAGNOSTICO DEMONSTRATIVO',[
        ['Modo','SIMULADO'],
        ['Fonte de dados','Gerador JavaScript local'],
        ['Interfaces',String(PORTS.length)],
        ['UP',String(up)],
        ['DOWN',String(down)],
        ['VLANs',String(VLANS.length)],
        ['Eventos ficticios',String(ALERTS.length)],
        ['Datasource Zabbix','NAO UTILIZADO'],
        ['Interface selecionada',state.selected]
      ]);
    }
  };

  const selector = $('mkd-interface-select');

  if (selector) {
    selector.innerHTML = PORTS.map(p =>
      '<option value="' + esc(p.name) + '">' +
      esc(p.name) + '</option>'
    ).join('');

    selector.value = state.selected;
    selector.onchange = function () {
      selectPort(selector.value);
    };
  }

  /* ======================================================
     ATUALIZACAO DOS DADOS SIMULADOS
     ====================================================== */

  function update() {
    state.tick++;

    updateKpis();
    buildPortCards();
    buildTable();
    drawChart();

    text('mkd-footer-status',
      'SIMULACAO ATIVA - ' +
      new Date().toLocaleTimeString('pt-BR')
    );
  }

  /* ======================================================
     INICIALIZACAO
     ====================================================== */

  buildRouter();
  buildPortCards();
  buildTable();
  buildVLANS();
  buildAlerts();
  updateKpis();
  drawChart();
  setupChartHover();

  text('mkd-footer-status', 'SIMULACAO ATIVA');

  rebuildCables();

  if (typeof ResizeObserver !== 'undefined') {
    const observer = new ResizeObserver(function () {
      rebuildCables();
    });

    observer.observe($('mkd-stage'));
    root._mkdObserver = observer;
  }

  root._mkdTimer = setInterval(update,4000);

  const reducedMotion =
    window.matchMedia &&
    window.matchMedia(
      '(prefers-reduced-motion: reduce)'
    ).matches;

  if (!reducedMotion) {
    root._mkdFrame = requestAnimationFrame(
      animationFrame
    );
  }

})();
